import { Controller } from "@hotwired/stimulus"
import { destroy, post } from "@rails/request.js"

const DRAGGED_CLASS = "drag-and-drop__dragged-item"
const HOVER_CLASS = "drag-and-drop__hover-container"

export default class extends Controller {
  #draggedCard = null
  #sourceColumn = null
  #hoverColumn = null

  dragstart(event) {
    const card = this.#cardFor(event.target)
    if (!card) return

    this.#draggedCard = card
    this.#sourceColumn = this.#columnFor(card)
    card.classList.add(DRAGGED_CLASS)
    card.setAttribute("aria-grabbed", "true")

    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = "move"
      event.dataTransfer.setData("text/plain", card.id)
    }
  }

  dragend() {
    this.#draggedCard?.classList.remove(DRAGGED_CLASS)
    this.#draggedCard?.removeAttribute("aria-grabbed")
    this.#clearHover()
    this.#draggedCard = null
    this.#sourceColumn = null
  }

  dragover(event) {
    const column = this.#columnFor(event.target)
    if (!column) {
      this.#clearHover()
      return
    }

    event.preventDefault()
    if (event.dataTransfer) event.dataTransfer.dropEffect = "move"
    if (this.#hoverColumn !== column) this.#setHover(column)
  }

  dragleave(event) {
    if (!this.element.contains(event.relatedTarget)) this.#clearHover()
  }

  drop(event) {
    const column = this.#columnFor(event.target)
    const card = this.#draggedCard
    this.#clearHover()

    if (!card || !column) return
    event.preventDefault()

    if (column === this.#sourceColumn) return

    const destination = this.#insertCard(card, column)
    this.#persist(card, column).catch(() => this.#revert(card, column, destination))
  }

  // private

  #cardFor(node) {
    return node.closest?.("[data-drag-and-drop-target='card']")
  }

  #columnFor(node) {
    return node.closest?.("[data-drag-and-drop-target='column']")
  }

  #setHover(column) {
    this.#clearHover()
    column.classList.add(HOVER_CLASS)
    this.#hoverColumn = column
  }

  #clearHover() {
    this.#hoverColumn?.classList.remove(HOVER_CLASS)
    this.#hoverColumn = null
  }

  #insertCard(card, column) {
    const list = column.querySelector(".cards__list")
    if (!list) return null

    const cards = list.querySelectorAll(".card")
    const firstNonGolden = Array.from(cards).find(c => !c.classList.contains("golden-effect"))

    if (firstNonGolden) {
      list.insertBefore(card, firstNonGolden)
    } else if (cards.length > 0) {
      cards[cards.length - 1].after(card)
    } else {
      list.prepend(card)
    }

    return list
  }

  async #persist(card, column) {
    const kind = column.dataset.dragAndDropKind

    switch (kind) {
      case "maybe":
        return await destroy(card.dataset.cardTriageUrl, { responseKind: "json" })
      case "not_now":
        return await post(card.dataset.cardNotNowUrl, { responseKind: "json" })
      case "closed":
        return await post(card.dataset.cardClosureUrl, { responseKind: "json" })
      default: {
        const body = new FormData()
        body.append("column_id", column.dataset.dragAndDropColumnId)
        return await post(card.dataset.cardTriageUrl, { body, responseKind: "json" })
      }
    }
  }

  #revert(card, column, list) {
    if (!list || !this.#sourceColumn) return
    const sourceList = this.#sourceColumn.querySelector(".cards__list")
    if (sourceList) sourceList.prepend(card)
  }
}
